package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Recovers the most recent framed serial byte and drives a local 8-bit bus segment. */
public class DeserializerBlock extends DirectionalDomainBlock{public DeserializerBlock(Properties p){super(p);}@Override public MapCodec<DeserializerBlock> codec(){return RedstoneEngineering.DESERIALIZER_CODEC.value();}private void update(ServerLevel l,BlockPos p,BlockState s){BlockPos in=inputPos(p,s),out=outputPos(p,s);int v=InformationRuntime.value(l,"serial",in);boolean ok=InformationRuntime.valid(l,"serial",in);InformationRuntime.write(l,"bus8_out",p,v,0,ok,100);if(l.getBlockState(out).getBlock() instanceof EightBitDataBusBlock)DataBusNetwork.resolve(l,DataBusNetwork.collect(l,out));}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block nb,BlockPos np,boolean m){if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Deserializer byte="+InformationRuntime.value(l,"bus8_out",p)),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
